    std::uint8_t *aCrystalLaneD = pWorkSpace->mCrystalLaneD;

    std::uint8_t *aLargeA = pWorkSpace->mCelestialLaneA;
    std::uint8_t *aLargeB = pWorkSpace->mCelestialLaneB;
    std::uint8_t *aLargeC = pWorkSpace->mCelestialLaneC;
    std::uint8_t *aLargeD = pWorkSpace->mCelestialLaneD;

    std::uint8_t *aMediumA = pWorkSpace->mAlchemyLaneA;
    std::uint8_t *aMediumB = pWorkSpace->mAlchemyLaneB;
    std::uint8_t *aMediumC = pWorkSpace->mAlchemyLaneC;
    std::uint8_t *aMediumD = pWorkSpace->mAlchemyLaneD;

    std::uint8_t *aSmallA = pWorkSpace->mAuguryLaneA;
    std::uint8_t *aSmallB = pWorkSpace->mAuguryLaneB;
