void TwistExpander_Regulus::KeyDiffuseA(TwistWorkSpace *pWorkSpace,
                                      const KeyDiffuseBundle &pBundle) {
    const KeyDiffuseLanes &aEntropy = pBundle.mEntropyA;
    const KeyDiffuseLanes &aInput = pBundle.mInputA;
    const KeyDiffuseLanes &aOutput = pBundle.mOutputA;
    TwistDomainConstants *aConstants = pBundle.mConstants;
    TwistDiffuse::KeyDiffuseWithDomainWords(
        aEntropy.mA, aEntropy.mB, aEntropy.mC, aEntropy.mD, // entropy lanes
        aInput.mA, aInput.mB, aInput.mC, aInput.mD, // input lanes
        aOutput.mA, aOutput.mB, aOutput.mC, aOutput.mD, // output lanes
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B, pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix, aConstants->mMatrixSelectA, aConstants->mMatrixSelectB, aConstants->mMatrixUnrollA, aConstants->mMatrixUnrollB,
        aConstants->mMatrixArgA, aConstants->mMatrixArgB, aConstants->mMatrixArgC, aConstants->mMatrixArgD);
}

void TwistExpander_Regulus::KeyDiffuseB(TwistWorkSpace *pWorkSpace,
                                      const KeyDiffuseBundle &pBundle) {
    const KeyDiffuseLanes &aEntropy = pBundle.mEntropyB;
    const KeyDiffuseLanes &aInput = pBundle.mInputB;
    const KeyDiffuseLanes &aOutput = pBundle.mOutputB;
    TwistDomainConstants *aConstants = pBundle.mConstants;
    TwistDiffuse::KeyDiffuseWithDomainWords(
        aEntropy.mA, aEntropy.mB, aEntropy.mC, aEntropy.mD, // entropy lanes
        aInput.mA, aInput.mB, aInput.mC, aInput.mD, // input lanes
        aOutput.mA, aOutput.mB, aOutput.mC, aOutput.mD, // output lanes
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B, pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix, aConstants->mMatrixSelectA, aConstants->mMatrixSelectB, aConstants->mMatrixUnrollA, aConstants->mMatrixUnrollB,
        aConstants->mMatrixArgA, aConstants->mMatrixArgB, aConstants->mMatrixArgC, aConstants->mMatrixArgD);
}

